// Plain data and small modules keep a future TypeScript migration straightforward.
export const uid = () => crypto.randomUUID();
export const tabs = {home:['⌂','Visão geral'],notes:['▤','Notas & documentos'],characters:['♙','Personagens'],plot:['⌘','Trama & plot'],bestiary:['♧','Bestiário'],maps:['♧','Atlas de mapas'],globe:['◎','Globo 3D']};
const now=()=>new Date().toISOString();
export function createWorld(name='As crônicas de Eldoria',demo=false){const id=uid(), f1=uid(),f2=uid();return {id,name,subtitle:demo?'Fantasia épica':'Um novo universo',enabled:Object.keys(tabs),folders:demo?[{id:f1,name:'O mundo de Eldoria'},{id:f2,name:'Ideias & inspirações'}]:[],notes:demo?[{id:uid(),title:'O início de tudo',folder:f1,body:'<p>Antes que os reinos tivessem nomes, o mundo era uma única floresta.</p><h2>Uma promessa esquecida</h2><p>Nas ruínas de um antigo santuário, uma jovem cartógrafa encontra um mapa que muda a cada amanhecer. As cidades desenhadas nele ainda não existem — mas algumas começam a desaparecer.</p><blockquote>E se conhecer o caminho fosse justamente o que nos impede de encontrá-lo?</blockquote><p>Uma história sobre pertencimento, memória e a coragem de partir.</p>',updated:now()},{id:uid(),title:'A magia tem um preço',folder:f1,body:'<h2>As regras do impossível</h2><p>Toda magia exige uma lembrança. Quanto maior o feitiço, mais preciosa a memória que se perde.</p><ul><li>A magia não pode criar vida.</li><li>Um nome verdadeiro nunca pode ser esquecido.</li><li>As florestas guardam o que os homens perderam.</li></ul>',updated:now()},{id:uid(),title:'Fragmentos de uma jornada',folder:f2,body:'<p>O cheiro de chuva sobre as pedras. Uma canção que ninguém se lembra de ter aprendido. O último fogo aceso antes da travessia.</p>',updated:now()}]:[],characters:demo?[{id:uid(),name:'Lyra Ventoalto',role:'Protagonista',species:'Humana',age:'24',description:'Uma cartógrafa que desenha lugares com os quais sonha. Curiosa, obstinada e incapaz de deixar um mistério para trás.',motivation:'Encontrar o irmão que desapareceu além das montanhas.',conflict:'Teme que cada novo mapa apague uma parte de sua própria história.',image:''},{id:uid(),name:'Aren do Vale',role:'Aliado',species:'Elfo',age:'137',description:'Guardião das fronteiras da floresta. Conhece todas as trilhas, mas perdeu o caminho de casa.',motivation:'Restaurar as memórias de seu povo.',conflict:'Precisa confiar em quem aprendeu a temer.',image:''}]:[],bestiary:demo?[{id:uid(),name:'Cervo das estrelas',role:'Espírito ancestral',species:'Criatura mágica',age:'Desconhecida',description:'Dizem que suas galhadas sustentam fragmentos do céu. Surge entre as árvores apenas quando alguém precisa encontrar o caminho.',motivation:'Floresta dos Sussurros',conflict:'Luz astral, orientação e cura. Desaparece diante de fogo.',image:'assets/stag.jpg'}]:[],plot:demo?[{id:uid(),title:'O mapa impossível',description:'Lyra encontra um mapa que revela cidades que ainda não existem.',act:'Ato I',status:'idea'},{id:uid(),title:'A travessia da floresta',description:'Uma aliança improvável se forma entre a cartógrafa e o guardião do vale.',act:'Ato II',status:'writing'},{id:uid(),title:'O último nome',description:'No coração da montanha, uma escolha mudará o destino de Eldoria.',act:'Ato III',status:'idea'}]:[],maps:[{id:uid(),name:demo?'Eldoria, o mundo conhecido':'Meu primeiro mapa',image:'assets/eldoria.svg',pins:demo?[{id:uid(),name:'Floresta dos Sussurros',x:22,y:33,description:'Uma floresta tão antiga quanto o mundo. Entre suas árvores, as memórias perdidas ganham voz. Nenhum viajante atravessa suas trilhas sem deixar algo de si para trás.',image:'assets/forest.jpg'},{id:uid(),name:'Porto de Alvorada',x:31,y:56,description:'O início de todas as jornadas. Um porto de mercadores, histórias e promessas.',image:'assets/journey.jpg'}]:[]}],updated:now()};}
export function load(){try{const d=JSON.parse(localStorage.getItem('aethra.v1'));if(d?.worlds?.length)return d;}catch{}const w=createWorld(undefined,true);return {version:1,current:w.id,theme:'light',worlds:[w]};}
export const state=load();
export const world=()=>state.worlds.find(w=>w.id===state.current)||state.worlds[0];
export function save(){world().updated=now();try{localStorage.setItem('aethra.v1',JSON.stringify(state));document.querySelector('#saveStatus').innerHTML='<i></i> Tudo salvo';return true;}catch{document.querySelector('#saveStatus').textContent='Armazenamento cheio';window.dispatchEvent(new CustomEvent('storagefull'));return false;}}
export const escapeHTML=(value='')=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function sanitize(html){const d=new DOMParser().parseFromString(html,'text/html');const allowed=new Set(['P','BR','DIV','SPAN','B','STRONG','I','EM','U','S','H1','H2','H3','UL','OL','LI','BLOCKQUOTE','A','FONT']);for(const el of [...d.body.querySelectorAll('*')]){if(['SCRIPT','STYLE','IFRAME','OBJECT','IMG','SVG','MATH'].includes(el.tagName)){el.remove();continue;}if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}for(const a of [...el.attributes]){const keep=el.tagName==='A'&&a.name==='href'&&/^(https?:|mailto:)/i.test(a.value)||el.tagName==='FONT'&&a.name==='color'&&/^#[\da-f]{3,8}$/i.test(a.value);if(!keep)el.removeAttribute(a.name);}if(el.tagName==='A'){el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer');}}return d.body.innerHTML;}
export const plain=html=>new DOMParser().parseFromString(html,'text/html').body.textContent||'';
export function imageURL(src){return /^(assets\/[\w.-]+|data:image\/(png|jpeg|webp);base64,[a-z\d+/=\s]+)$/i.test(src||'')?src:'';}
export async function imageFile(file){if(!file?.type.startsWith('image/'))throw Error('Escolha um arquivo de imagem.');if(file.size>25*1024*1024)throw Error('A imagem deve ter até 25 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.85);}
